using BARANG.Core.Domain.Inventory;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace BARANG.Core.Infrastructure.Persistence.Configurations;

internal static class InventoryConfiguration
{
    internal static void Base<T>(EntityTypeBuilder<T> b) where T:class { b.HasKey("Id"); b.Property("Id").HasColumnName("id"); b.Property("CompanyId").HasColumnName("company_id"); }
    internal static void Quantity<T>(EntityTypeBuilder<T>b,string property,string column)where T:class=>b.Property<decimal>(property).HasColumnName(column).HasPrecision(18,4);
    internal static void Version<T>(EntityTypeBuilder<T>b)where T:class=>b.Property<long>("Version").HasColumnName("version").IsConcurrencyToken();
}
internal sealed class StockTransactionConfiguration:IEntityTypeConfiguration<StockTransaction>{public void Configure(EntityTypeBuilder<StockTransaction>b){b.ToTable("stock_transactions",t=>t.HasCheckConstraint("ck_stock_transactions_quantity","quantity_delta <> 0"));InventoryConfiguration.Base(b);b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");b.Property(x=>x.TransactionType).HasColumnName("transaction_type").HasConversion<string>().HasMaxLength(24);InventoryConfiguration.Quantity(b,nameof(StockTransaction.QuantityDelta),"quantity_delta");b.Property(x=>x.UomCode).HasColumnName("uom_code").HasMaxLength(50);b.Property(x=>x.SourceType).HasColumnName("source_type").HasMaxLength(50);b.Property(x=>x.SourceId).HasColumnName("source_id");b.Property(x=>x.Reference).HasColumnName("reference").HasMaxLength(150);b.Property(x=>x.ReasonCode).HasColumnName("reason_code").HasMaxLength(100);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.CorrelationId).HasColumnName("correlation_id").HasMaxLength(100);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.HasIndex(x=>new{x.CompanyId,x.Reference}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.WarehouseId,x.ProductVariantId,x.OccurredAtUtc});Refs(b,x=>x.WarehouseId,x=>x.ProductVariantId);}
static void Refs(EntityTypeBuilder<StockTransaction>b,System.Linq.Expressions.Expression<Func<StockTransaction,Guid>>w,System.Linq.Expressions.Expression<Func<StockTransaction,Guid>>v){b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Catalog.ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class StockBalanceConfiguration:IEntityTypeConfiguration<StockBalance>{public void Configure(EntityTypeBuilder<StockBalance>b){b.ToTable("stock_balances",t=>{t.HasCheckConstraint("ck_stock_balances_on_hand","on_hand >= 0");t.HasCheckConstraint("ck_stock_balances_reserved","reserved >= 0 AND reserved <= on_hand");});InventoryConfiguration.Base(b);b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");InventoryConfiguration.Quantity(b,nameof(StockBalance.OnHand),"on_hand");InventoryConfiguration.Quantity(b,nameof(StockBalance.Reserved),"reserved");b.Ignore(x=>x.Available);b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.WarehouseId,x.ProductVariantId}).IsUnique();b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Catalog.ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class StockReservationConfiguration:IEntityTypeConfiguration<StockReservation>{public void Configure(EntityTypeBuilder<StockReservation>b){b.ToTable("stock_reservations",t=>{t.HasCheckConstraint("ck_stock_reservations_qty","requested_quantity > 0 AND reserved_quantity > 0 AND remaining_quantity >= 0 AND remaining_quantity <= reserved_quantity");});InventoryConfiguration.Base(b);b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");foreach(var p in new[]{nameof(StockReservation.RequestedQuantity),nameof(StockReservation.ReservedQuantity),nameof(StockReservation.RemainingQuantity)})InventoryConfiguration.Quantity(b,p,System.Text.Json.JsonNamingPolicy.SnakeCaseLower.ConvertName(p));b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(24);b.Property(x=>x.ExpiresAtUtc).HasColumnName("expires_at_utc");b.Property(x=>x.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(150);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.IdempotencyKey}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.ExpiresAtUtc});b.HasOne<Domain.Orders.OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Catalog.ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class StockTransferConfiguration:IEntityTypeConfiguration<StockTransfer>{public void Configure(EntityTypeBuilder<StockTransfer>b){b.ToTable("stock_transfers",t=>t.HasCheckConstraint("ck_stock_transfers_qty","quantity > 0"));InventoryConfiguration.Base(b);b.Property(x=>x.SourceWarehouseId).HasColumnName("source_warehouse_id");b.Property(x=>x.DestinationWarehouseId).HasColumnName("destination_warehouse_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");InventoryConfiguration.Quantity(b,nameof(StockTransfer.Quantity),"quantity");b.Property(x=>x.UomCode).HasColumnName("uom_code").HasMaxLength(50);b.Property(x=>x.Reference).HasColumnName("reference").HasMaxLength(150);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.Reference}).IsUnique();b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SourceWarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.DestinationWarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Catalog.ProductVariant>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ProductVariantId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class StockShortageConfiguration:IEntityTypeConfiguration<StockShortage>{public void Configure(EntityTypeBuilder<StockShortage>b){b.ToTable("stock_shortages");InventoryConfiguration.Base(b);b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");foreach(var p in new[]{nameof(StockShortage.RequiredQuantity),nameof(StockShortage.AvailableQuantity),nameof(StockShortage.ShortageQuantity)})InventoryConfiguration.Quantity(b,p,System.Text.Json.JsonNamingPolicy.SnakeCaseLower.ConvertName(p));b.Property(x=>x.IsActive).HasColumnName("is_active");b.Property(x=>x.ProposalStatus).HasColumnName("proposal_status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.PurchaseRequestId).HasColumnName("purchase_request_id");b.Property(x=>x.LastRecheckedAtUtc).HasColumnName("last_rechecked_at_utc");b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.OrderItemId,x.WarehouseId}).IsUnique().HasFilter("is_active");b.HasIndex(x=>new{x.CompanyId,x.PurchaseRequestId}).IsUnique().HasFilter("purchase_request_id IS NOT NULL");}}
internal sealed class PurchaseRequestConfiguration:IEntityTypeConfiguration<PurchaseRequest>{public void Configure(EntityTypeBuilder<PurchaseRequest>b){b.ToTable("purchase_requests");InventoryConfiguration.Base(b);b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.RequestedByUserId).HasColumnName("requested_by_user_id");b.Property(x=>x.RequestNumber).HasColumnName("request_number").HasMaxLength(40);b.Property(x=>x.Reason).HasColumnName("reason").HasMaxLength(500);b.Property(x=>x.SourceShortageId).HasColumnName("source_shortage_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.SourceShortageId}).IsUnique().HasFilter("source_shortage_id IS NOT NULL");b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PurchaseRequestItemConfiguration:IEntityTypeConfiguration<PurchaseRequestItem>{public void Configure(EntityTypeBuilder<PurchaseRequestItem>b){b.ToTable("purchase_request_items",t=>t.HasCheckConstraint("ck_purchase_request_items_qty","requested_quantity > 0"));InventoryConfiguration.Base(b);b.Property(x=>x.PurchaseRequestId).HasColumnName("purchase_request_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");InventoryConfiguration.Quantity(b,nameof(PurchaseRequestItem.RequestedQuantity),"requested_quantity");b.HasOne<PurchaseRequest>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PurchaseRequestId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PurchaseOrderConfiguration:IEntityTypeConfiguration<PurchaseOrder>{public void Configure(EntityTypeBuilder<PurchaseOrder>b){b.ToTable("purchase_orders");InventoryConfiguration.Base(b);b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.SupplierId).HasColumnName("supplier_id");b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.PurchaseOrderNumber).HasColumnName("purchase_order_number").HasMaxLength(40);b.Property(x=>x.CurrencyCode).HasColumnName("currency_code").HasMaxLength(3).IsFixedLength();b.Property(x=>x.ExpectedDeliveryDate).HasColumnName("expected_delivery_date");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(24);b.Property(x=>x.ClosureReason).HasColumnName("closure_reason").HasMaxLength(500);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");InventoryConfiguration.Version(b);b.HasIndex(x=>new{x.CompanyId,x.PurchaseOrderNumber}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.Status,x.CreatedAtUtc});b.HasOne<Domain.Catalog.Supplier>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.SupplierId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PurchaseOrderItemConfiguration:IEntityTypeConfiguration<PurchaseOrderItem>{public void Configure(EntityTypeBuilder<PurchaseOrderItem>b){b.ToTable("purchase_order_items",t=>t.HasCheckConstraint("ck_purchase_order_items_values","ordered_quantity > 0 AND unit_purchase_price >= 0"));InventoryConfiguration.Base(b);b.HasAlternateKey(x=>new{x.CompanyId,x.Id});b.Property(x=>x.PurchaseOrderId).HasColumnName("purchase_order_id");b.Property(x=>x.ProductVariantId).HasColumnName("product_variant_id");InventoryConfiguration.Quantity(b,nameof(PurchaseOrderItem.OrderedQuantity),"ordered_quantity");b.Property(x=>x.UnitPurchasePrice).HasColumnName("unit_purchase_price").HasPrecision(18,2);b.HasOne<PurchaseOrder>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PurchaseOrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PurchaseReceiptConfiguration:IEntityTypeConfiguration<PurchaseReceipt>{public void Configure(EntityTypeBuilder<PurchaseReceipt>b){b.ToTable("purchase_receipts",t=>t.HasCheckConstraint("ck_purchase_receipts_qty","quantity > 0"));InventoryConfiguration.Base(b);b.Property(x=>x.PurchaseOrderId).HasColumnName("purchase_order_id");b.Property(x=>x.PurchaseOrderItemId).HasColumnName("purchase_order_item_id");b.Property(x=>x.StockTransactionId).HasColumnName("stock_transaction_id");InventoryConfiguration.Quantity(b,nameof(PurchaseReceipt.Quantity),"quantity");b.Property(x=>x.Reference).HasColumnName("reference").HasMaxLength(150);b.Property(x=>x.ReceiptNumber).HasColumnName("receipt_number").HasMaxLength(40).IsRequired();b.Property(x=>x.ReceivedByUserId).HasColumnName("received_by_user_id");b.Property(x=>x.ReceivedAtUtc).HasColumnName("received_at_utc");b.HasIndex(x=>new{x.CompanyId,x.Reference}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.ReceiptNumber}).IsUnique();b.HasOne<PurchaseOrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PurchaseOrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
